// 9LMNTS Studio Canonical Pricing & PayPal E-Commerce Engine
const body = $input.item.json.body || $input.item.json;
const action = body.action || (body.function_name || 'create_paypal_ecommerce_order');
const params = body.parameters || body;

const pricingMatrix = {
  'starter_sprint': { title: 'Starter Sprint', amount: 1500, payIn4: true },
  'pro_custom_sprint': { title: 'Pro Custom Sprint', amount: 2500, payIn4: true },
  'enterprise_build': { title: 'Enterprise Scale Build', amount: 5000, payIn4: false },
  'pro_retainer': { title: 'Pro Monthly Retainer', amount: 1500, recurring: true },
  'premier_retainer': { title: 'Premier Operations Retainer', amount: 2500, recurring: true },
  'enterprise_retainer': { title: 'Enterprise Custom Retainer', amount: 5000, recurring: true },
  'box_01_cover': { title: 'General Admission Cover & Ballot', amount: 20, payIn4: true },
  'box_02_tip': { title: 'Micro-Tip & Drink Credit', amount: 10, payIn4: false },
  'box_03_hype': { title: 'Power Hype Pack (25x Votes)', amount: 50, payIn4: true },
  'box_04_vip': { title: 'VIP Hospitality Table', amount: 150, payIn4: true }
};

let itemTitle = params.service_title || 'Agency Sprint / Pass';
let amount = parseFloat(params.amount_cad || 1500);
let planType = params.payment_plan_type || 'pay_in_4';
let clientEmail = params.client_email || 'client@example.com';
let clientName = params.client_name || 'Valued Client';

let installmentBreakdown = null;
if (amount >= 20 && amount <= 3500) {
  const perInstallment = (amount / 4).toFixed(2);
  installmentBreakdown = {
    plan_name: 'PayPal Pay in 4',
    installments: 4,
    amount_per_installment: `$${perInstallment} CAD`,
    frequency: 'Bi-weekly',
    interest_rate: '0% APR',
    total_financed: `$${amount.toFixed(2)} CAD`
  };
}

const txnRef = 'PAYID-' + Math.random().toString(36).substring(2, 10).toUpperCase();
const checkoutSessionUrl = `https://www.paypal.com/checkoutnow?token=EC-${txnRef}&client_email=${encodeURIComponent(clientEmail)}&amt=${amount}&plan=${planType}`;

return {
  json: {
    status: 'success',
    timestamp: new Date().toISOString(),
    order_id: txnRef,
    client: {
      name: clientName,
      email: clientEmail
    },
    service: {
      title: itemTitle,
      total_amount_cad: amount,
      payment_plan_selected: planType,
      paypal_pay_in_4_details: installmentBreakdown
    },
    paypal_checkout_url: checkoutSessionUrl,
    settlement_rail: 'PayPal E-Commerce Services (Complete Payments Platform)',
    message: `Order for ${itemTitle} initialized. Total: $${amount} CAD. Pay in 4 option: ${installmentBreakdown ? installmentBreakdown.amount_per_installment + ' every 2 weeks' : 'N/A'}. Proceed to checkout.`
  }
};
